SELECT * FROM reservations
WHERE business_id = #{businessId}
ORDER BY reservation_date DESC, start_time DESC

SELECT * FROM reservations
WHERE customer_id = #{customerId}
ORDER BY reservation_date DESC, start_time DESC

SELECT * FROM reservations
WHERE staff_id = #{staffId}
ORDER BY reservation_date DESC, start_time DESC

SELECT * FROM reservations
WHERE business_id = #{businessId}
  AND reservation_date = #{date}
ORDER BY start_time

SELECT * FROM reservations
WHERE business_id = #{businessId}
  AND reservation_date BETWEEN #{startDate} AND #{endDate}
ORDER BY reservation_date, start_time

SELECT * FROM reservations
WHERE business_id = #{businessId}
  AND status = #{status}
ORDER BY reservation_date DESC, start_time DESC

SELECT * FROM reservations
WHERE 1=1

    AND business_id = #{businessId}


    AND customer_id = #{customerId}


    AND staff_id = #{staffId}


    AND status = #{status}


    AND reservation_date BETWEEN #{startDate} AND #{endDate}


    AND reservation_date >= #{startDate}


    AND reservation_date <= #{endDate}

ORDER BY reservation_date DESC, start_time DESC

SELECT * FROM reservations
WHERE staff_id = #{staffId}
  AND reservation_date = #{date}
  AND status IN ('PENDING', 'CONFIRMED')
  AND (
    (#{startTime} >= start_time AND #{startTime} < end_time)
        OR (#{endTime} > start_time AND #{endTime} <= end_time)
        OR (#{startTime} <= start_time AND #{endTime} >= end_time)
    )

SELECT EXISTS(
    SELECT 1 FROM reservations
    WHERE business_id = #{businessId} AND id = #{id}
)

SELECT EXISTS(
    SELECT 1 FROM reservations
    WHERE reservation_number = #{reservationNumber}
)

SELECT COUNT(*)
FROM reservations
WHERE business_id = #{businessId}
  AND reservation_date = #{date}

SELECT COUNT(*)
FROM reservations
WHERE business_id = #{businessId}
  AND reservation_date = #{date}
  AND status = #{status}

SELECT COUNT(*)
FROM reservations
WHERE business_id = #{businessId}
  AND reservation_date BETWEEN #{startDate} AND #{endDate}

SELECT COALESCE(SUM(total_price), 0)
FROM reservations
WHERE business_id = #{businessId}
  AND reservation_date BETWEEN #{startDate} AND #{endDate}
  AND status = #{status}

SELECT COALESCE(SUM(total_price), 0)
FROM reservations
WHERE business_id = #{businessId}
